INSERT INTO feature VALUES('law-discharge','modules','Laws a model leaves out, discharged','stated-laws','partial','notable',NULL,'A law a model leaves out is stated at the law''s type with no body, and the checker discharges it by `Path.here` at its left side, under the law''s binders, where its sides convert. The model writes nothing the conversion already shows, and the kernel replays the minted body as a written one. A law whose sides part is refused `NoFiller.Omitted` by its name. `gandr check --report cells` prints each discharged law with its module and its source. The derived and the generated sources are #4141 and #4142.','core-checker surface-lowering surface-corpus surface-driver','corpus/ledger/diagnostics/NoFiller.Omitted.gandr corpus/pathological/modules/model-laws.gandr corpus/pathological/higher-cells/path-cells.gandr crates/surface-driver/tests/cli.rs corpus/model/modules/model-laws.gandr','corpus/ledger/features/law-discharge.gandr','#4141 #4142');
